namespace SecretCustomer.Core.Interfaces.Services;

public interface ISmsService
{
    /// <summary>
    /// Tekil SMS gönderimi
    /// </summary>
    Task<bool> SendSmsAsync(string phoneNumber, string message);

    /// <summary>
    /// Toplu SMS gönderimi
    /// </summary>
    Task<int> SendBulkSmsAsync(List<(string phoneNumber, string message)> messages);

    /// <summary>
    /// Assignment için form linki SMS'i gönder
    /// </summary>
    Task<bool> SendFormLinkSmsAsync(string phoneNumber, string recipientName, string formLink);

    /// <summary>
    /// SMS bakiye kontrolü (provider'a göre)
    /// </summary>
    Task<decimal?> GetCreditBalanceAsync();
}

using System.Text;
using System.Web;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using SecretCustomer.Core.Interfaces.Services;

namespace SecretCustomer.Services.Services;

public class NetgsmSmsService : ISmsService
{
    private readonly HttpClient _httpClient;
    private readonly IConfiguration _configuration;
    private readonly ILogger<NetgsmSmsService> _logger;

    private string Username => _configuration["SmsSettings:Netgsm:Username"] ?? "";
    private string Password => _configuration["SmsSettings:Netgsm:Password"] ?? "";
    private string Header => _configuration["SmsSettings:Netgsm:Header"] ?? "GIZLIMUSTERI";
    private string ApiUrl => "https://api.netgsm.com.tr/sms/send/get";

    public NetgsmSmsService(
        HttpClient httpClient,
        IConfiguration configuration,
        ILogger<NetgsmSmsService> logger)
    {
        _httpClient = httpClient;
        _configuration = configuration;
        _logger = logger;
    }

    public async Task<bool> SendSmsAsync(string phoneNumber, string message)
    {
        try
        {
            // Telefon numarasını temizle (başındaki 0 veya +90'ı kaldır)
            var cleanedPhone = CleanPhoneNumber(phoneNumber);

            var url = $"{ApiUrl}?" +
                      $"usercode={Username}&" +
                      $"password={Password}&" +
                      $"gsmno={cleanedPhone}&" +
                      $"message={HttpUtility.UrlEncode(message, Encoding.GetEncoding("ISO-8859-9"))}&" +
                      $"msgheader={Header}&" +
                      $"dil=TR";

            var response = await _httpClient.GetAsync(url);
            var result = await response.Content.ReadAsStringAsync();

            // Netgsm response format: "00 [messageId]" = başarılı
            if (result.StartsWith("00"))
            {
                _logger.LogInformation($"SMS sent successfully to {phoneNumber}. Response: {result}");
                return true;
            }

            _logger.LogWarning($"SMS send failed to {phoneNumber}. Response: {result}");
            return false;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"SMS send error to {phoneNumber}");
            return false;
        }
    }

    public async Task<int> SendBulkSmsAsync(List<(string phoneNumber, string message)> messages)
    {
        int successCount = 0;
        foreach (var (phoneNumber, message) in messages)
        {
            var success = await SendSmsAsync(phoneNumber, message);
            if (success) successCount++;

            // Rate limiting - SMS provider'ları saniyede max 10-20 SMS kabul eder
            await Task.Delay(100);
        }

        return successCount;
    }

    public async Task<bool> SendFormLinkSmsAsync(string phoneNumber, string recipientName, string formLink)
    {
        // SMS mesaj şablonu
        var message = $"Sayin {recipientName},\n" +
                      $"Lutfen asagidaki linke tiklayarak degerlendirme formunu doldurunuz:\n" +
                      $"{formLink}\n" +
                      $"Tesekkur ederiz.";

        return await SendSmsAsync(phoneNumber, message);
    }

    public async Task<decimal?> GetCreditBalanceAsync()
    {
        try
        {
            var url = $"https://api.netgsm.com.tr/balance/list/get?" +
                      $"usercode={Username}&" +
                      $"password={Password}";

            var response = await _httpClient.GetAsync(url);
            var result = await response.Content.ReadAsStringAsync();

            // Response: "00 1234.56" (kredi miktarı)
            if (result.StartsWith("00"))
            {
                var parts = result.Split(' ');
                if (parts.Length > 1 && decimal.TryParse(parts[1], out var balance))
                {
                    return balance;
                }
            }

            return null;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to get SMS credit balance");
            return null;
        }
    }

    private string CleanPhoneNumber(string phoneNumber)
    {
        // +905551234567 -> 5551234567
        // 905551234567  -> 5551234567
        // 05551234567   -> 5551234567

        var cleaned = phoneNumber.Replace("+", "").Replace(" ", "").Replace("-", "");

        if (cleaned.StartsWith("90"))
            cleaned = cleaned.Substring(2);

        if (cleaned.StartsWith("0"))
            cleaned = cleaned.Substring(1);

        return cleaned;
    }
}

private readonly ISmsService _smsService;  // YENİ

public AssignmentService(
    IAssignmentRepository assignmentRepository,
    IProjectRepository projectRepository,
    IChecklistRepository checklistRepository,
    ISmsService smsService)  // YENİ
{
    _assignmentRepository = assignmentRepository;
    _projectRepository = projectRepository;
    _checklistRepository = checklistRepository;
    _smsService = smsService;
}

public async Task<AssignmentDto> CreateAsync(CreateAssignmentDto dto)
{
    await ValidateAsync(dto);

    var assignment = new Assignment
    {
        ProjectId = dto.ProjectId,
        ChecklistId = dto.ChecklistId,
        BranchId = dto.BranchId,
        AssignedUserId = dto.AssignedUserId,
        ExternalEmail = dto.ExternalEmail,
        ExternalName = dto.ExternalName,
        ExternalPhone = dto.ExternalPhone,  // YENİ
        UniqueLink = Guid.NewGuid().ToString(),
        DueDate = dto.DueDate,
        IsCompleted = false
    };

    var created = await _assignmentRepository.CreateAsync(assignment);

    // SMS gönderimi (eğer telefon varsa)
    if (!string.IsNullOrEmpty(dto.ExternalPhone) && dto.SendSms)
    {
        var formLink = $"https://yourdomain.com/form/{created.UniqueLink}";
        await _smsService.SendFormLinkSmsAsync(
            dto.ExternalPhone,
            dto.ExternalName ?? "Değerli Müşterimiz",
            formLink);
    }

    return MapToDto(created);
}

[HttpPost("{id}/send-sms")]
public async Task<IActionResult> SendFormSms(Guid id)
{
    var assignment = await _assignmentService.GetByIdAsync(id);
    if (assignment == null)
        return NotFound();

    if (string.IsNullOrEmpty(assignment.ExternalPhone))
        return BadRequest("Assignment does not have a phone number");

    var formLink = $"{Request.Scheme}://{Request.Host}/form/{assignment.UniqueLink}";

    var success = await _smsService.SendFormLinkSmsAsync(
        assignment.ExternalPhone,
        assignment.ExternalName ?? "Değerli Müşterimiz",
        formLink);

    if (success)
        return Ok(new { message = "SMS sent successfully" });

    return StatusCode(500, new { message = "SMS send failed" });
}

[HttpGet("sms/balance")]
public async Task<ActionResult<decimal?>> GetSmsBalance()
{
    var balance = await _smsService.GetCreditBalanceAsync();
    return Ok(new { balance, currency = "TL" });
}
